/* ============================================================
   PERSISTENCE (localStorage)
   ============================================================ */
const DB = {
  load()        { return JSON.parse(localStorage.getItem('ca_data_v2') || 'null'); },
  save(d)       { localStorage.setItem('ca_data_v2', JSON.stringify(d)); },
  session()     { return JSON.parse(sessionStorage.getItem('ca_user') || 'null'); },
  setSession(u) { sessionStorage.setItem('ca_user', JSON.stringify(u)); },
  clearSession(){ sessionStorage.removeItem('ca_user'); },
};

