/* ============================================================
   ROUTER
   ============================================================ */
function navigate(page) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
  const target = document.getElementById(`page-${page}`);
  if (!target) return;
  target.classList.add('active');
  state.currentPage = page;
  const navItem = document.querySelector(`.nav-item[data-page="${page}"]`);
  if (navItem) navItem.classList.add('active');
  const labels = { 'new-bill':'New Invoice', invoices:'Invoices', products:'Menu Items', analytics:'Analytics' };
  document.getElementById('breadcrumb').textContent = labels[page] || page;
  closeSidebar();
  if (page === 'invoices')   renderInvoices();
  if (page === 'products')   renderProducts();
  if (page === 'analytics')  renderAnalytics();
  if (page === 'new-bill')   initNewBill();
}

/* ============================================================
   AUTH
   ============================================================ */
function initAuth() {
  document.querySelectorAll('.auth-tab').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.auth-tab, .auth-form').forEach(el => el.classList.remove('active'));
      btn.classList.add('active');
      document.getElementById(`${btn.dataset.tab}-form`).classList.add('active');
    });
  });

  document.getElementById('login-form').addEventListener('submit', e => {
    e.preventDefault();
    const email = document.getElementById('login-email').value.trim();
    const pass  = document.getElementById('login-password').value;
    clearErrors('login-email-err','login-pass-err');
    if (!email) { showError('login-email-err','Email required'); return; }
    if (!pass)  { showError('login-pass-err','Password required'); return; }
    const d    = DB.load();
    const user = d.users.find(u => u.email === email && u.password === pass);
    if (!user) { showError('login-pass-err','Invalid email or password'); return; }
    loginUser(user);
  });

  document.getElementById('signup-form').addEventListener('submit', e => {
    e.preventDefault();
    const fname = document.getElementById('signup-fname').value.trim();
    const lname = document.getElementById('signup-lname').value.trim();
    const biz   = document.getElementById('signup-biz').value.trim();
    const email = document.getElementById('signup-email').value.trim();
    const pass  = document.getElementById('signup-password').value;
    if (!fname || !email || !pass) { showToast('Please fill all required fields','error'); return; }
    if (pass.length < 8) { showToast('Password must be at least 8 characters','error'); return; }
    const d = DB.load();
    if (d.users.find(u => u.email === email)) { showToast('Email already registered','error'); return; }
    const user = { id:`u_${Date.now()}`, email, password:pass, firstName:fname, lastName:lname, businessName:biz||'Coffee Aroma' };
    d.users.push(user);
    DB.save(d);
    loginUser(user);
    showToast('Account created! Welcome ☕','success');
  });
}

function loginUser(user) {
  state.currentUser = user;
  DB.setSession(user);
  document.getElementById('auth-screen').classList.remove('active');
  document.getElementById('main-app').classList.add('active');
  document.getElementById('user-avatar').textContent       = user.firstName[0].toUpperCase();
  document.getElementById('user-name-display').textContent = user.firstName + ' ' + user.lastName;
  document.getElementById('user-biz-display').textContent  = user.businessName;
  const hour = new Date().getHours();
  const greet = hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening';
  navigate('invoices');
}

function logout() {
  state.currentUser = null;
  DB.clearSession();
  document.getElementById('main-app').classList.remove('active');
  document.getElementById('auth-screen').classList.add('active');
  state.invoices = []; state.products = [];
  showToast('Logged out successfully','info');
}

/* ============================================================
   DATA HELPERS
   ============================================================ */
function getData()      { return DB.load() || initDB(); }
function saveData(d)    { DB.save(d); }

function clearAllInvoices() {
  if (!confirm('Delete ALL invoices and start fresh?\nThis cannot be undone.')) return;
  const d = getData();
  d.invoices   = [];
  d.invoiceSeq = 1;
  DB.save(d);
  showToast('All invoices cleared. Starting fresh! ☕', 'success');
  if (state.currentPage === 'invoices')  renderInvoices();
}
function getProducts()  { return getData().products; }
function getInvoices()  { return getData().invoices; }

function nextInvoiceNumber() {
  const d = DB.load();
  const num = `INV-${String(d.invoiceSeq).padStart(4,'0')}`;
  // Animate the badge if field is visible
  const badge = document.getElementById('inv-num-badge');
  if (badge) {
    badge.style.transition = 'none';
    badge.style.color = '#6b3a2a';
    badge.style.fontWeight = '700';
    setTimeout(() => {
      badge.style.transition = 'color .6s, font-weight .6s';
      badge.style.color = '#a0896b';
      badge.style.fontWeight = '400';
    }, 300);
  }
  return num;
}
function incSeq() {
  const d = DB.load(); d.invoiceSeq++; DB.save(d);
}

/* ============================================================
   NEW BILL
   ============================================================ */
/* POS state */
let posSearchTerm = '';
let posCatFilter  = '';

function initNewBill() {
  document.getElementById('invoice-date').value   = new Date().toISOString().split('T')[0];
  // Always read fresh seq from DB so number is correct after previous bills
  const freshNum = `INV-${String(DB.load().invoiceSeq).padStart(4,'0')}`;
  document.getElementById('invoice-number').value = freshNum;
  // Only reset cart if coming fresh (not returning mid-order)
  if (!state.lineItems.length) state.lineItems = [];
  renderPOSProductGrid();
  renderPOSCart();
  calcSummary();
}

/* ---- POS Product Grid ---- */
function renderPOSProductGrid() {
  const products = getProducts();
  const cats = [...new Set(products.map(p => p.category))].sort();

  // Category tabs
  const tabWrap = document.getElementById('pos-cat-tabs');
  if (tabWrap) {
    tabWrap.innerHTML = `<button class="pos-cat-btn${!posCatFilter?' active':''}" onclick="setPOSCat('')">All</button>` +
      cats.map(c => `<button class="pos-cat-btn${c===posCatFilter?' active':''}" onclick="setPOSCat('${esc(c)}')">${esc(c)}</button>`).join('');
  }

  // Filter
  let filtered = products;
  if (posCatFilter) filtered = filtered.filter(p => p.category === posCatFilter);
  if (posSearchTerm) filtered = filtered.filter(p => p.name.toLowerCase().includes(posSearchTerm) || p.category.toLowerCase().includes(posSearchTerm));

  const grid = document.getElementById('pos-products-grid');
  if (!grid) return;
  if (!filtered.length) {
    grid.innerHTML = '<div class="pos-no-results">No items found</div>';
    return;
  }
  grid.innerHTML = filtered.map(p => {
    const inCart = state.lineItems.find(l => l.prodId === p.id);
    const qty = inCart ? inCart.qty : 0;
    return `<div class="pos-product-card${qty>0?' in-cart':''}" onclick="posAddProduct('${p.id}')">
      <div class="pos-prod-emoji">${p.emoji||'🍽️'}</div>
      <div class="pos-prod-name">${esc(p.name)}</div>
      <div class="pos-prod-cat">${esc(p.category)}</div>
      <div class="pos-prod-price">${fmt(p.price)}</div>
      ${qty>0 ? `<div class="pos-prod-badge">${qty}</div>` : ''}
    </div>`;
  }).join('');
}

function setPOSCat(cat) {
  posCatFilter = cat;
  renderPOSProductGrid();
}

function posSearch(val) {
  posSearchTerm = val.trim().toLowerCase();
  renderPOSProductGrid();
}

function posAddProduct(productId) {
  const p = getProducts().find(prod => prod.id === productId);
  if (!p) return;
  const existing = state.lineItems.find(l => l.prodId === productId);
  if (existing) {
    existing.qty++;
    existing.amount = +(existing.qty * existing.rate).toFixed(2);
  } else {
    state.lineItems.push({
      id: Date.now(), prodId: productId,
      name: p.name, qty: 1, rate: p.price, tax: p.tax, amount: p.price
    });
  }
  renderPOSProductGrid();
  renderPOSCart();
  calcSummary();
}

/* ---- POS Cart ---- */
function renderPOSCart() {
  const container = document.getElementById('pos-cart-items');
  if (!container) return;
  if (!state.lineItems.length) {
    container.innerHTML = '<div class="pos-cart-empty">Tap a product to add it</div>';
    return;
  }
  container.innerHTML = state.lineItems.map(item => {
    if (!item.prodId) {
      // Manual item — show editable row
      return `<div class="pos-cart-row" data-id="${item.id}">
        <div class="pos-cart-item-info" style="flex:1">
          <input type="text" class="pos-manual-name" placeholder="Item name" value="${esc(item.name)}"
            oninput="posManualChange(${item.id},'name',this.value)" style="width:100%;padding:.3rem .5rem;border:1.5px solid var(--parchment);border-radius:6px;font-size:.8rem;margin-bottom:.25rem"/>
          <div style="display:flex;gap:.35rem">
            <input type="number" placeholder="Rate" value="${item.rate}" min="0" step="0.5"
              oninput="posManualChange(${item.id},'rate',this.value)" style="width:70px;padding:.25rem .4rem;border:1.5px solid var(--parchment);border-radius:6px;font-size:.78rem"/>
            <input type="number" placeholder="Tax%" value="${item.tax}" min="0" max="28" step=".5"
              oninput="posManualChange(${item.id},'tax',this.value)" style="width:55px;padding:.25rem .4rem;border:1.5px solid var(--parchment);border-radius:6px;font-size:.78rem"/>
            <span style="font-size:.78rem;color:var(--muted);align-self:center">${fmt(item.amount)}</span>
          </div>
        </div>
        <div class="pos-cart-qty-ctrl">
          <button class="pos-qty-btn" onclick="posCartQtyChange(${item.id},-1)">−</button>
          <span class="pos-cart-qty">${item.qty}</span>
          <button class="pos-qty-btn" onclick="posCartQtyChange(${item.id},1)">+</button>
        </div>
        <button class="btn-delete-row" onclick="removeLineItemPOS(${item.id})" title="Remove">✕</button>
      </div>`;
    }
    return `<div class="pos-cart-row" data-id="${item.id}">
      <div class="pos-cart-item-info">
        <div class="pos-cart-item-name">${esc(item.name)}</div>
        <div class="pos-cart-item-price">${fmt(item.rate)} × ${item.qty} = <strong>${fmt(item.amount)}</strong></div>
      </div>
      <div class="pos-cart-qty-ctrl">
        <button class="pos-qty-btn" onclick="posCartQtyChange(${item.id},-1)">−</button>
        <span class="pos-cart-qty">${item.qty}</span>
        <button class="pos-qty-btn" onclick="posCartQtyChange(${item.id},1)">+</button>
      </div>
      <button class="btn-delete-row" onclick="removeLineItemPOS(${item.id})" title="Remove">✕</button>
    </div>`;
  }).join('');
}

function posManualChange(id, field, val) {
  const item = state.lineItems.find(l => l.id === id);
  if (!item) return;
  if (field === 'name') item.name = val;
  if (field === 'rate') item.rate = parseFloat(val)||0;
  if (field === 'tax')  item.tax  = parseFloat(val)||0;
  item.amount = +(item.qty * item.rate).toFixed(2);
  calcSummary();
}

function posCartQtyChange(id, delta) {
  const item = state.lineItems.find(l => l.id === id);
  if (!item) return;
  item.qty = Math.max(1, item.qty + delta);
  item.amount = +(item.qty * item.rate).toFixed(2);
  renderPOSProductGrid();
  renderPOSCart();
  calcSummary();
}

function removeLineItemPOS(id) {
  state.lineItems = state.lineItems.filter(l => l.id !== id);
  renderPOSProductGrid();
  renderPOSCart();
  calcSummary();
}

function addLineItem() {
  // Manual add to cart
  state.lineItems.push({ id:Date.now(), prodId:null, name:'', qty:1, rate:0, tax:5, amount:0 });
  renderPOSCart();
  calcSummary();
}

function removeLineItem(id) {
  state.lineItems = state.lineItems.filter(l => l.id !== id);
  renderPOSProductGrid();
  renderPOSCart();
  calcSummary();
}

function renderLineItems() {
  // Legacy shim — UI rendering handled by renderPOSCart
}

function onItemChange(id, field, val) {
  const item = state.lineItems.find(l => l.id === id);
  if (!item) return;
  if (field === 'qty')  item.qty  = Math.max(1, parseFloat(val)||1);
  if (field === 'rate') item.rate = parseFloat(val)||0;
  if (field === 'tax')  item.tax  = parseFloat(val)||0;
  item.amount = +(item.qty * item.rate).toFixed(2);
  const el = document.getElementById(`item-total-${id}`);
  if (el) el.textContent = fmt(item.amount);
  calcSummary();
}

function onItemNameInput(input, id) {
  const item = state.lineItems.find(l => l.id === id);
  if (item) item.name = input.value;
  showAC(input, id);
}

function showAC(input, id) {
  const q        = input.value.trim().toLowerCase();
  const dropdown = document.getElementById(`ac-${id}`);
  if (!dropdown) return;
  const products = getProducts();
  const matches  = q ? products.filter(p => p.name.toLowerCase().includes(q) || p.category.toLowerCase().includes(q)) : products.slice(0,6);
  if (!matches.length) { dropdown.classList.remove('show'); return; }
  dropdown.innerHTML = matches.map(p => `
    <div class="ac-item" onmousedown="selectAC(${id},'${esc(p.name)}',${p.price},${p.tax})">
      <span class="ac-item-name">${p.emoji} ${esc(p.name)}</span>
      <span class="ac-item-price">${fmt(p.price)}</span>
    </div>`).join('');
  dropdown.classList.add('show');
}

function hideAC(id) {
  const el = document.getElementById(`ac-${id}`);
  if (el) el.classList.remove('show');
}

function selectAC(id, name, rate, tax) {
  const item = state.lineItems.find(l => l.id === id);
  if (!item) return;
  item.name = name; item.rate = rate; item.tax = tax;
  item.amount = +(item.qty * rate).toFixed(2);
  renderLineItems(); calcSummary(); hideAC(id);
}

function calcSummary() {
  const subtotal = state.lineItems.reduce((s,l) => s + (l.qty * l.rate), 0);
  const cgstRate = parseFloat(document.getElementById('cgst-rate').value)||0;
  const sgstRate = parseFloat(document.getElementById('sgst-rate').value)||0;
  const svcRate  = parseFloat(document.getElementById('service-charge').value)||0;
  const discVal  = parseFloat(document.getElementById('discount-val').value)||0;
  const discType = document.getElementById('discount-type').value;
  const cgst     = +(subtotal * cgstRate / 100).toFixed(2);
  const sgst     = +(subtotal * sgstRate / 100).toFixed(2);
  const service  = +(subtotal * svcRate  / 100).toFixed(2);
  const discount = discType === 'pct' ? +(subtotal * discVal / 100).toFixed(2) : +discVal.toFixed(2);
  const total    = Math.max(0, +(subtotal + cgst + sgst + service - discount).toFixed(2));
  document.getElementById('sum-subtotal').textContent = fmt(subtotal);
  document.getElementById('sum-cgst').textContent     = fmt(cgst);
  document.getElementById('sum-sgst').textContent     = fmt(sgst);
  document.getElementById('sum-service').textContent  = fmt(service);
  document.getElementById('sum-discount').textContent = `-${fmt(discount)}`;
  document.getElementById('sum-total').textContent    = fmt(total);
  return { subtotal, cgst, sgst, service, discount, total };
}

function generateBill() {
  const clientName = document.getElementById('client-name').value.trim();
  if (!clientName) { showError('client-name-err','Customer name is required'); showToast('Please enter customer name','error'); return; }
  if (state.lineItems.every(l => !l.name || l.rate === 0)) { showToast('Add at least one item with a price','error'); return; }
  const nums   = calcSummary();
  const d      = getData();
  const invNum = nextInvoiceNumber();
  const invoice = {
    id: `inv_${Date.now()}`,
    number:      invNum,
    clientName,
    clientEmail: document.getElementById('client-email').value.trim(),
    clientPhone: document.getElementById('client-phone').value.trim(),
    date:        document.getElementById('invoice-date').value,
    orderType:   document.getElementById('order-type').value,
    items:       state.lineItems.filter(l => l.name && l.rate > 0).map(l => ({ name:l.name, qty:l.qty, rate:l.rate, tax:l.tax, amount:+(l.qty*l.rate).toFixed(2) })),
    ...nums,
    notes:       document.getElementById('bill-notes').value.trim(),
    status:      'pending',
    createdAt:   new Date().toISOString(),
  };
  d.invoices.unshift(invoice);
  DB.save(d);
  incSeq();                         // bump seq BEFORE clearBillForm reads it
  showToast(`Invoice ${invNum} created!`, 'success');
  state.lineItems = [];
  clearBillForm();
  setTimeout(() => openInvoiceModal(invoice.id), 400);
}

function clearBillForm() {
  ['client-name','client-email','client-phone','bill-notes'].forEach(id => { document.getElementById(id).value = ''; });
  document.getElementById('discount-val').value    = '0';
  document.getElementById('service-charge').value  = '0';
  document.getElementById('invoice-date').value    = new Date().toISOString().split('T')[0];
  state.lineItems = [];
  renderPOSCart();
  renderPOSProductGrid();
  calcSummary();
  // Always pull fresh seq from DB after incSeq has run
  const freshNum = `INV-${String(DB.load().invoiceSeq).padStart(4,'0')}`;
  document.getElementById('invoice-number').value = freshNum;
  const badge = document.getElementById('inv-num-badge');
  if (badge) { badge.style.color='#6b3a2a'; badge.style.fontWeight='700';
    setTimeout(()=>{ badge.style.color='#a0896b'; badge.style.fontWeight='400'; },400); }
}

/* ============================================================
   INVOICES LIST
   ============================================================ */
function renderInvoices() {
  let invoices = getInvoices();
  const f      = state.invFilter;
  if (f.search)  invoices = invoices.filter(i => i.clientName.toLowerCase().includes(f.search) || i.number.toLowerCase().includes(f.search));
  if (f.status)  invoices = invoices.filter(i => i.status === f.status);
  if (f.from)    invoices = invoices.filter(i => i.date >= f.from);
  if (f.to)      invoices = invoices.filter(i => i.date <= f.to);

  const [sortKey, sortDir] = f.sort.split('-');
  invoices.sort((a,b) => {
    let va, vb;
    if (sortKey === 'date')   { va = a.date;       vb = b.date; }
    if (sortKey === 'amount') { va = a.total;       vb = b.total; }
    if (sortKey === 'number') { va = a.number;      vb = b.number; }
    if (sortKey === 'client') { va = a.clientName;  vb = b.clientName; }
    if (typeof va === 'string') return sortDir === 'asc' ? va.localeCompare(vb) : vb.localeCompare(va);
    return sortDir === 'asc' ? va - vb : vb - va;
  });

  const total  = invoices.length;
  const pages  = Math.ceil(total / ITEMS_PER_PAGE) || 1;
  state.invPage = Math.min(state.invPage, pages);
  const start  = (state.invPage - 1) * ITEMS_PER_PAGE;
  const page   = invoices.slice(start, start + ITEMS_PER_PAGE);

  const tbody = document.getElementById('invoices-tbody');
  if (!page.length) {
    tbody.innerHTML = '<tr><td colspan="7" class="empty-state small">No invoices match your search</td></tr>';
  } else {
    tbody.innerHTML = page.map(inv => `
      <tr>
        <td><span class="inv-num-cell">${inv.number}</span></td>
        <td>${esc(inv.clientName)}</td>
        <td>${fmtDate(inv.date)}</td>
        <td>${inv.orderType||'Dine In'}</td>
        <td><span class="inv-amount-cell">${fmt(inv.total)}</span></td>
        <td><span class="badge ${inv.status}">${inv.status}</span></td>
        <td>
          <div class="inv-actions">
            <button class="inv-btn view" onclick="openInvoiceModal('${inv.id}')">View</button>
            <button class="inv-btn pdf"  onclick="downloadPDF('${inv.id}')">PDF</button>
          </div>
        </td>
      </tr>`).join('');
  }

  document.getElementById('inv-page-info').textContent = `Showing ${total} invoice${total!==1?'s':''}`;
  const btnWrap = document.getElementById('inv-page-btns');
  btnWrap.innerHTML = '';
  if (pages > 1) {
    const prev = Object.assign(document.createElement('button'),{className:'page-btn',textContent:'←',disabled:state.invPage===1});
    prev.onclick = () => { state.invPage--; renderInvoices(); };
    btnWrap.appendChild(prev);
    for (let p=1; p<=pages; p++) {
      if (pages > 7 && Math.abs(p - state.invPage) > 2 && p !== 1 && p !== pages) {
        if (Math.abs(p - state.invPage) === 3) { const dots=document.createElement('span'); dots.textContent='…'; dots.style.padding='0 .3rem'; btnWrap.appendChild(dots); }
        continue;
      }
      const btn = Object.assign(document.createElement('button'),{className:`page-btn${p===state.invPage?' active':''}`,textContent:p});
      btn.onclick = (pp => () => { state.invPage=pp; renderInvoices(); })(p);
      btnWrap.appendChild(btn);
    }
    const next = Object.assign(document.createElement('button'),{className:'page-btn',textContent:'→',disabled:state.invPage===pages});
    next.onclick = () => { state.invPage++; renderInvoices(); };
    btnWrap.appendChild(next);
  }
}

/* ============================================================
   INVOICE MODAL / VIEW
   ============================================================ */
function openInvoiceModal(id) {
  const inv = getInvoices().find(i => i.id === id);
  if (!inv) return;
  state.currentInvoiceId = id;
  document.getElementById('inv-preview-content').innerHTML = buildInvoiceHTML(inv);
  document.getElementById('invoice-view-modal').classList.add('active');
  const paid = document.getElementById('inv-modal-status-paid');
  paid.textContent = inv.status === 'paid' ? '✓ Paid' : 'Mark as Paid';
  paid.disabled = inv.status === 'paid';
}

