/* ============================================================
   PRODUCTS
   ============================================================ */
function renderProducts() {
  const products = getProducts();
  const search   = state.prodFilter.search.toLowerCase();
  const cat      = state.prodFilter.category;
  let filtered   = products;
  if (search) filtered = filtered.filter(p => p.name.toLowerCase().includes(search) || p.category.toLowerCase().includes(search));
  if (cat)    filtered = filtered.filter(p => p.category === cat);

  const cats     = [...new Set(products.map(p => p.category))].sort();
  const chipWrap = document.getElementById('category-chips');
  chipWrap.innerHTML = `<button class="chip${!cat?' active':''}" data-cat="">All</button>` +
    cats.map(c => `<button class="chip${c===cat?' active':''}" data-cat="${esc(c)}">${esc(c)}</button>`).join('');
  chipWrap.querySelectorAll('.chip').forEach(btn => {
    btn.addEventListener('click', () => { state.prodFilter.category = btn.dataset.cat; renderProducts(); });
  });

  const grid = document.getElementById('products-grid');
  if (!filtered.length) {
    grid.innerHTML = '<div class="empty-state"><div class="empty-icon">🍽️</div><div class="empty-title">No items found</div></div>';
    return;
  }
  grid.innerHTML = filtered.map(p => `
    <div class="product-card">
      <span class="product-emoji">${p.emoji||'🍽️'}</span>
      <div class="product-name">${esc(p.name)}</div>
      <div class="product-category">${esc(p.category)} · ${p.unit}</div>
      <div class="product-price">${fmt(p.price)}</div>
      <div style="font-size:.75rem;color:var(--muted);margin-top:.25rem">Tax: ${p.tax}%</div>
      ${p.desc ? `<div style="font-size:.78rem;color:var(--warm-gray);margin-top:.375rem;line-height:1.4">${esc(p.desc)}</div>` : ''}
      <div class="product-card-actions">
        <button class="btn-secondary btn-sm" onclick="editProduct('${p.id}')">Edit</button>
        <button class="btn-secondary btn-sm btn-danger" onclick="deleteProduct('${p.id}')">Delete</button>
      </div>
    </div>`).join('');
}

function openProductModal(product = null) {
  document.getElementById('product-modal-title').textContent  = product ? 'Edit Menu Item' : 'Add Menu Item';
  document.getElementById('product-id').value       = product ? product.id : '';
  document.getElementById('product-emoji').value    = product ? product.emoji||'' : '☕';
  document.getElementById('product-name').value     = product ? product.name : '';
  document.getElementById('product-category').value = product ? product.category : '';
  document.getElementById('product-price').value    = product ? product.price : '';
  document.getElementById('product-desc').value     = product ? product.desc||'' : '';
  document.getElementById('product-tax').value      = product ? product.tax : '5';
  document.getElementById('product-unit').value     = product ? product.unit : 'cup';
  document.getElementById('product-modal').classList.add('active');
}

function editProduct(id) {
  const p = getProducts().find(p => p.id === id);
  if (p) openProductModal(p);
}

function deleteProduct(id) {
  if (!confirm('Delete this menu item?')) return;
  const d = getData();
  d.products = d.products.filter(p => p.id !== id);
  DB.save(d);
  showToast('Item deleted','info');
  renderProducts();
}

function saveProduct(e) {
  e.preventDefault();
  const name  = document.getElementById('product-name').value.trim();
  const price = parseFloat(document.getElementById('product-price').value);
  clearErrors('prod-name-err','prod-price-err');
  if (!name)                     { showError('prod-name-err','Name required'); return; }
  if (isNaN(price) || price < 0) { showError('prod-price-err','Valid price required'); return; }
  const d       = getData();
  const id      = document.getElementById('product-id').value;
  const product = {
    id:       id || `p_${Date.now()}`,
    name,
    emoji:    document.getElementById('product-emoji').value || '☕',
    category: document.getElementById('product-category').value.trim() || 'General',
    price,
    desc:     document.getElementById('product-desc').value.trim(),
    tax:      parseFloat(document.getElementById('product-tax').value)||0,
    unit:     document.getElementById('product-unit').value,
  };
  if (id) {
    const idx = d.products.findIndex(p => p.id === id);
    if (idx > -1) d.products[idx] = product;
  } else {
    d.products.unshift(product);
  }
  DB.save(d);
  document.getElementById('product-modal').classList.remove('active');
  showToast(id ? 'Item updated!' : 'Item added!','success');
  renderProducts();
}

/* ============================================================
   ANALYTICS
   ============================================================ */
function renderAnalytics() {
  const invoices = getInvoices();

  const catSales = {};
  invoices.forEach(inv => (inv.items||[]).forEach(item => {
    const prod = getProducts().find(p => p.name === item.name);
    const cat  = prod ? prod.category : 'Other';
    catSales[cat] = (catSales[cat]||0) + item.amount;
  }));
  const cCtx = document.getElementById('category-chart');
  if (state.categoryChart) state.categoryChart.destroy();
  const catEntries = Object.entries(catSales).sort((a,b)=>b[1]-a[1]);
  state.categoryChart = new Chart(cCtx, {
    type:'doughnut',
    data:{ labels:catEntries.map(([k])=>k), datasets:[{ data:catEntries.map(([,v])=>v), backgroundColor:['#6b3a2a','#4a9e6a','#4a7cbf','#9b5e2a','#8b5cf6','#e87040','#c8862e'], borderWidth:2, borderColor:'#fdf6ec' }] },
    options:{ responsive:true, plugins:{ legend:{position:'bottom',labels:{font:{family:'DM Sans',size:11},padding:12}}, tooltip:{callbacks:{label:c=>`${c.label}: ${CURRENCY}${c.raw.toFixed(0)}`}} } }
  });

  const typeSales = {};
  invoices.forEach(inv => { typeSales[inv.orderType||'Dine In'] = (typeSales[inv.orderType||'Dine In']||0)+1; });
  const oCtx = document.getElementById('order-type-chart');
  if (state.orderTypeChart) state.orderTypeChart.destroy();
  const typeEntries = Object.entries(typeSales);
  state.orderTypeChart = new Chart(oCtx, {
    type:'pie',
    data:{ labels:typeEntries.map(([k])=>k), datasets:[{ data:typeEntries.map(([,v])=>v), backgroundColor:['#6b3a2a','#4a9e6a','#4a7cbf','#e87040'], borderWidth:2, borderColor:'#fdf6ec' }] },
    options:{ responsive:true, plugins:{ legend:{position:'bottom',labels:{font:{family:'DM Sans',size:11},padding:12}} } }
  });
}

/* ============================================================
   EXPORT PASSWORD PROTECTION
   ============================================================ */
/* Password stored as encoded segments — not visible as plain text in UI */
const _EP = (()=>{ const p=['Ar','om','a@','93','84']; return p.join(''); })();

let _pendingExportFn = null; // stores the export callback after password verified

function requireExportPassword(onSuccess) {
  _pendingExportFn = onSuccess;
  document.getElementById('export-verify-password').value = '';
  document.getElementById('export-pw-error').textContent  = '';
  document.getElementById('export-password-modal').classList.add('active');
  setTimeout(() => document.getElementById('export-verify-password').focus(), 100);
}

function verifyExportPassword() {
  const entered = document.getElementById('export-verify-password').value;
  if (entered === _EP) {
    document.getElementById('export-password-modal').classList.remove('active');
    document.getElementById('export-pw-error').textContent = '';
    if (_pendingExportFn) { _pendingExportFn(); _pendingExportFn = null; }
  } else {
    document.getElementById('export-pw-error').textContent = '❌ Incorrect password. Please try again.';
    document.getElementById('export-verify-password').value = '';
    document.getElementById('export-verify-password').focus();
  }
}

function togglePwVisibility() {
  const inp = document.getElementById('export-verify-password');
  inp.type = inp.type === 'password' ? 'text' : 'password';
}

/* ============================================================
   EXCEL EXPORT
   ============================================================ */
function openExportModal() {
  // Set default dates
  const today     = new Date().toISOString().split('T')[0];
  document.getElementById('export-date-from').value = today;
  document.getElementById('export-date-to').value   = today;
  document.getElementById('export-status').value    = '';

  // Reset period buttons
  state.exportPeriod = 'today';
  document.querySelectorAll('.period-btn').forEach(b => b.classList.remove('active'));
  document.querySelector('.period-btn[data-period="today"]').classList.add('active');
  document.getElementById('custom-range-fields').style.display = 'none';

  updateExportPreview();
  document.getElementById('export-modal').classList.add('active');
}

function getExportDateRange() {
  const today = new Date();
  let from, to;
  const fmt = d => d.toISOString().split('T')[0];

  if (state.exportPeriod === 'today') {
    from = to = fmt(today);
  } else if (state.exportPeriod === 'week') {
    const start = new Date(today);
    start.setDate(today.getDate() - today.getDay());
    from = fmt(start); to = fmt(today);
  } else if (state.exportPeriod === 'month') {
    from = `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-01`;
    to   = fmt(today);
  } else {
    // custom
    from = document.getElementById('export-date-from').value;
    to   = document.getElementById('export-date-to').value;
  }
  return { from, to };
}

function updateExportPreview() {
  const { from, to } = getExportDateRange();
  const statusFilter = document.getElementById('export-status').value;
  let invoices = getInvoices();
  if (from) invoices = invoices.filter(i => i.date >= from);
  if (to)   invoices = invoices.filter(i => i.date <= to);
  if (statusFilter) invoices = invoices.filter(i => i.status === statusFilter);

  const total = invoices.reduce((s,i) => s + i.total, 0);
  const el    = document.getElementById('export-preview-count');
  el.textContent = `${invoices.length} invoice${invoices.length!==1?'s':''} · Total: ${fmt(total)}`;
}

function doExport() {
  // Always require password verification before export
  requireExportPassword(() => _doExportActual());
}

function _doExportActual() {
  const { from, to } = getExportDateRange();
  const statusFilter = document.getElementById('export-status').value;

  let invoices = getInvoices();
  if (from) invoices = invoices.filter(i => i.date >= from);
  if (to)   invoices = invoices.filter(i => i.date <= to);
  if (statusFilter) invoices = invoices.filter(i => i.status === statusFilter);
  invoices.sort((a,b) => a.date.localeCompare(b.date));

  if (!invoices.length) {
    showToast('No invoices found for selected criteria','error');
    return;
  }

  // ── Build Excel workbook ──
  const wb = XLSX.utils.book_new();

  // Sheet 1: Invoice Summary
  const summaryRows = [
    [`Coffee Aroma — Invoice Report`],
    [`Generated: ${new Date().toLocaleString('en-IN')}`],
    [`Period: ${from || 'All'} to ${to || 'All'}`],
    [],
    ['Invoice #', 'Customer Name', 'Phone', 'Email', 'Date', 'Order Type', 'Items', 'Subtotal (₹)', 'CGST (₹)', 'SGST (₹)', 'Service (₹)', 'Discount (₹)', 'Total (₹)', 'Status', 'Notes'],
  ];

  invoices.forEach(inv => {
    const itemsSummary = (inv.items||[]).map(it => `${it.name} x${it.qty}`).join(', ');
    summaryRows.push([
      inv.number,
      inv.clientName,
      inv.clientPhone || '',
      inv.clientEmail || '',
      inv.date,
      inv.orderType || 'Dine In',
      itemsSummary,
      +parseFloat(inv.subtotal).toFixed(2),
      +parseFloat(inv.cgst).toFixed(2),
      +parseFloat(inv.sgst).toFixed(2),
      +parseFloat(inv.serviceCharge||0).toFixed(2),
      +parseFloat(inv.discount||0).toFixed(2),
      +parseFloat(inv.total).toFixed(2),
      inv.status,
      inv.notes || '',
    ]);
  });

  // Totals row
  const totalRevenue = invoices.reduce((s,i) => s + i.total, 0);
  summaryRows.push([]);
  summaryRows.push(['', '', '', '', '', '', 'TOTAL', '', '', '', '', '', +totalRevenue.toFixed(2), '', '']);

  const ws1 = XLSX.utils.aoa_to_sheet(summaryRows);
  ws1['!cols'] = [
    {wch:12},{wch:22},{wch:14},{wch:24},{wch:12},{wch:14},
    {wch:40},{wch:14},{wch:10},{wch:10},{wch:12},{wch:12},{wch:14},{wch:10},{wch:24}
  ];
  XLSX.utils.book_append_sheet(wb, ws1, 'Invoice Summary');

  // Sheet 2: Item-level breakdown
  const itemRows = [
    [`Coffee Aroma — Item Breakdown`],
    [],
    ['Invoice #', 'Date', 'Customer', 'Item Name', 'Qty', 'Unit Price (₹)', 'Tax %', 'Line Total (₹)'],
  ];
  invoices.forEach(inv => {
    (inv.items||[]).forEach(item => {
      itemRows.push([
        inv.number,
        inv.date,
        inv.clientName,
        item.name,
        item.qty,
        +parseFloat(item.rate).toFixed(2),
        item.tax,
        +parseFloat(item.amount).toFixed(2),
      ]);
    });
  });
  const ws2 = XLSX.utils.aoa_to_sheet(itemRows);
  ws2['!cols'] = [{wch:12},{wch:12},{wch:22},{wch:28},{wch:6},{wch:16},{wch:8},{wch:14}];
  XLSX.utils.book_append_sheet(wb, ws2, 'Item Breakdown');

  // Sheet 3: Stats
  const paid    = invoices.filter(i => i.status === 'paid');
  const pending = invoices.filter(i => i.status === 'pending');
  const statsRows = [
    ['Coffee Aroma — Report Statistics'],
    [],
    ['Metric', 'Value'],
    ['Total Invoices', invoices.length],
    ['Paid Invoices',  paid.length],
    ['Pending Invoices', pending.length],
    ['Total Revenue (₹)', +totalRevenue.toFixed(2)],
    ['Paid Revenue (₹)',  +paid.reduce((s,i) => s+i.total, 0).toFixed(2)],
    ['Pending Revenue (₹)', +pending.reduce((s,i) => s+i.total, 0).toFixed(2)],
    ['Avg Invoice Value (₹)', +(totalRevenue / invoices.length).toFixed(2)],
    ['Report Period', `${from || 'All'} to ${to || 'All'}`],
    ['Generated At', new Date().toLocaleString('en-IN')],
  ];
  const ws3 = XLSX.utils.aoa_to_sheet(statsRows);
  ws3['!cols'] = [{wch:26},{wch:24}];
  XLSX.utils.book_append_sheet(wb, ws3, 'Statistics');

  const periodLabel = from === to ? from : `${from}_to_${to}`;
  const fileName    = `CoffeeAroma_Invoices_${periodLabel}`;

  XLSX.writeFile(wb, `${fileName}.xlsx`);
  showToast(`Excel exported: ${fileName}.xlsx`, 'success');
  document.getElementById('export-modal').classList.remove('active');
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a   = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { URL.revokeObjectURL(url); a.remove(); }, 1000);
}

function loadScript(src) {
  return new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = src; s.onload = resolve; s.onerror = reject;
    document.head.appendChild(s);
  });
}

/* ============================================================
   GLOBAL SEARCH
   ============================================================ */
function doGlobalSearch(q) {
  q = q.toLowerCase().trim();
  if (!q) return;
  navigate('invoices');
  state.invFilter.search = q;
  document.getElementById('inv-search').value = q;
  state.invPage = 1;
  renderInvoices();
}

/* ============================================================
   UTILS
   ============================================================ */
function fmt(n) {
  n = parseFloat(n)||0;
  return `${CURRENCY}${n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
}
function fmtDate(d) {
  if (!d) return '';
  return new Date(d).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
}
function esc(s) {
  if (!s) return '';
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function showError(id, msg) {
  const el = document.getElementById(id); if (el) el.textContent = msg;
}
function clearErrors(...ids) {
  ids.forEach(id => { const el = document.getElementById(id); if (el) el.textContent = ''; });
}
function showToast(msg, type='info') {
  const container = document.getElementById('toast-container');
  const toast     = document.createElement('div');
  toast.className = `toast ${type}`;
  toast.innerHTML = `<div class="toast-icon"></div><span class="toast-msg">${msg}</span><button class="toast-close" onclick="this.parentElement.remove()">✕</button>`;
  container.appendChild(toast);
  setTimeout(() => { toast.style.opacity='0'; toast.style.transform='translateX(30px)'; toast.style.transition='all .3s'; setTimeout(()=>toast.remove(),300); }, 3500);
}
function closeSidebar() {
  document.getElementById('sidebar').classList.remove('mobile-open');
  document.getElementById('sidebar-overlay').classList.remove('active');
}

/* ============================================================
   INIT
   ============================================================ */
document.addEventListener('DOMContentLoaded', () => {
  initDB();

  /* -- AUTH -- */
  initAuth();
  const session = DB.session();
  if (session) loginUser(session);

  /* -- SIDEBAR -- */
  document.getElementById('menu-toggle').addEventListener('click', () => {
    document.getElementById('sidebar').classList.toggle('mobile-open');
    document.getElementById('sidebar-overlay').classList.toggle('active');
  });
  document.getElementById('sidebar-close').addEventListener('click', closeSidebar);
  document.getElementById('sidebar-overlay').addEventListener('click', closeSidebar);
  document.getElementById('btn-logout').addEventListener('click', logout);

  /* -- NAVIGATION -- */
  document.addEventListener('click', e => {
    const el = e.target.closest('[data-page]');
    if (el && !el.classList.contains('auth-tab')) navigate(el.dataset.page);
  });
  document.getElementById('new-bill-quick').addEventListener('click', () => navigate('new-bill'));

  /* -- GLOBAL SEARCH -- */
  let searchTimer;
  document.getElementById('global-search').addEventListener('input', e => {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => doGlobalSearch(e.target.value), 400);
  });
  document.getElementById('global-search').addEventListener('keydown', e => {
    if (e.key === 'Enter') doGlobalSearch(e.target.value);
  });

  /* -- BILL FORM -- */
  // pos manual add handled inline
  ['cgst-rate','sgst-rate','discount-val','discount-type','service-charge'].forEach(id => {
    document.getElementById(id).addEventListener('input', calcSummary);
  });
  document.getElementById('btn-generate-bill').addEventListener('click', generateBill);
  document.getElementById('btn-clear-bill').addEventListener('click', () => {
    if (confirm('Clear the form?')) clearBillForm();
  });

  /* -- INVOICE FILTERS -- */
  document.getElementById('inv-search').addEventListener('input', e => {
    state.invFilter.search = e.target.value.toLowerCase(); state.invPage=1; renderInvoices();
  });
  document.getElementById('inv-status-filter').addEventListener('change', e => {
    state.invFilter.status = e.target.value; state.invPage=1; renderInvoices();
  });
  document.getElementById('inv-sort').addEventListener('change', e => {
    state.invFilter.sort = e.target.value; renderInvoices();
  });
  document.getElementById('inv-date-from').addEventListener('change', e => {
    state.invFilter.from = e.target.value; state.invPage=1; renderInvoices();
  });
  document.getElementById('inv-date-to').addEventListener('change', e => {
    state.invFilter.to = e.target.value; state.invPage=1; renderInvoices();
  });

  /* -- EXPORT EXCEL BUTTON -- */
  document.getElementById('btn-export-excel').addEventListener('click', openExportModal);

  /* -- EXPORT MODAL CONTROLS -- */
  document.getElementById('export-modal-close').addEventListener('click', () => document.getElementById('export-modal').classList.remove('active'));
  document.getElementById('export-modal-cancel').addEventListener('click', () => document.getElementById('export-modal').classList.remove('active'));
  document.getElementById('btn-do-export').addEventListener('click', doExport);

  /* -- EXPORT PASSWORD MODAL CONTROLS -- */
  document.getElementById('export-pw-modal-close').addEventListener('click', () => {
    document.getElementById('export-password-modal').classList.remove('active');
    _pendingExportFn = null;
  });
  document.getElementById('export-pw-cancel').addEventListener('click', () => {
    document.getElementById('export-password-modal').classList.remove('active');
    _pendingExportFn = null;
  });
  document.getElementById('export-pw-confirm').addEventListener('click', verifyExportPassword);
  document.getElementById('export-verify-password').addEventListener('keydown', e => {
    if (e.key === 'Enter') verifyExportPassword();
  });

  // Period selection buttons
  document.getElementById('export-period-btns').addEventListener('click', e => {
    const btn = e.target.closest('.period-btn');
    if (!btn) return;
    document.querySelectorAll('.period-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    state.exportPeriod = btn.dataset.period;
    document.getElementById('custom-range-fields').style.display = state.exportPeriod === 'custom' ? 'block' : 'none';
    updateExportPreview();
  });

  document.getElementById('export-date-from').addEventListener('change', updateExportPreview);
  document.getElementById('export-date-to').addEventListener('change', updateExportPreview);
  document.getElementById('export-status').addEventListener('change', updateExportPreview);

  /* -- PRODUCTS -- */
  document.getElementById('add-product-btn').addEventListener('click', () => openProductModal());
  document.getElementById('product-form').addEventListener('submit', saveProduct);
  document.getElementById('product-modal-close').addEventListener('click', () => document.getElementById('product-modal').classList.remove('active'));
  document.getElementById('product-modal-cancel').addEventListener('click', () => document.getElementById('product-modal').classList.remove('active'));
  document.getElementById('prod-search').addEventListener('input', e => {
    state.prodFilter.search = e.target.value; renderProducts();
  });

  /* -- INVOICE MODAL -- */
  document.getElementById('inv-modal-close').addEventListener('click', () => document.getElementById('invoice-view-modal').classList.remove('active'));
  document.getElementById('inv-modal-status-paid').addEventListener('click', () => {
    if (state.currentInvoiceId) markInvoicePaid(state.currentInvoiceId);
  });
  document.getElementById('inv-modal-pdf').addEventListener('click', () => {
    if (state.currentInvoiceId) downloadPDF(state.currentInvoiceId);
  });

  /* -- CLOSE MODALS ON BACKDROP -- */
  document.querySelectorAll('.modal-backdrop').forEach(bd => {
    bd.addEventListener('click', e => { if (e.target === bd) bd.classList.remove('active'); });
  });

  /* -- KEYBOARD -- */
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') document.querySelectorAll('.modal-backdrop.active').forEach(m => m.classList.remove('active'));
  });
});

